FeatureScript 3083;
import(path : "onshape/std/common.fs", version : "3083.0");

// Generated by fsgen (paste export). Paste into a Feature Studio, then add the feature
// to a Part Studio from the toolbar. Parameters appear in the feature dialog.

// Midpoint of an arc from its endpoints; k = tan(sweep / 4) keeps the arc's sweep when parameters change.
function arcMid(a is Vector, b is Vector, k is number) returns Vector
{
    var d = b - a;
    return (a + b) / 2 + vector(d[1], -d[0]) * (k / 2);
}

annotation { "Feature Type Name" : "Tap collar base" }
export const tapCollarBase = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Length" }
        isLength(definition.length, { (millimeter) : [0, 60, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Depth" }
        isLength(definition.depth, { (millimeter) : [0, 18, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Block height" }
        isLength(definition.blockHeight, { (millimeter) : [0, 14, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Cradle diameter" }
        isLength(definition.cradleDiameter, { (millimeter) : [0, 34, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Cradle height" }
        isLength(definition.cradleHeight, { (millimeter) : [0, 29.25, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Tower stop" }
        isLength(definition.towerStop, { (millimeter) : [0, 17.25, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Tower width" }
        isLength(definition.towerWidth, { (millimeter) : [0, 9.95, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Tower height" }
        isLength(definition.towerHeight, { (millimeter) : [0, 21, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Tower fillet radius" }
        isLength(definition.towerFilletRadius, { (millimeter) : [0, 1.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Hole diameter" }
        isLength(definition.holeDiameter, { (millimeter) : [0, 3.4, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Hole spacing" }
        isLength(definition.holeSpacing, { (millimeter) : [0, 48, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Countersink diameter" }
        isLength(definition.countersinkDiameter, { (millimeter) : [0, 6, 10000] } as LengthBoundSpec);
    }
    {
    // Body sketch
    var bodySketchSk = newSketchOnPlane(context, id + "bodySketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(bodySketchSk, "outline_0", { "start" : vector(-definition.length / 2, (0 * millimeter)), "end" : vector(definition.length / 2, (0 * millimeter)) });
    skLineSegment(bodySketchSk, "outline_1", { "start" : vector(definition.length / 2, (0 * millimeter)), "end" : vector(definition.length / 2, definition.blockHeight) });
    skLineSegment(bodySketchSk, "outline_2", { "start" : vector(definition.length / 2, definition.blockHeight), "end" : vector(definition.towerStop + definition.towerWidth, definition.blockHeight) });
    skLineSegment(bodySketchSk, "outline_3", { "start" : vector(definition.towerStop + definition.towerWidth, definition.blockHeight), "end" : vector(definition.towerStop + definition.towerWidth, definition.towerHeight) });
    skLineSegment(bodySketchSk, "outline_4", { "start" : vector(definition.towerStop + definition.towerWidth, definition.towerHeight), "end" : vector(definition.towerStop, definition.towerHeight) });
    skLineSegment(bodySketchSk, "outline_5", { "start" : vector(definition.towerStop, definition.towerHeight), "end" : vector(definition.towerStop, definition.blockHeight) });
    skLineSegment(bodySketchSk, "outline_6", { "start" : vector(definition.towerStop, definition.blockHeight), "end" : vector(-definition.length / 2, definition.blockHeight) });
    skLineSegment(bodySketchSk, "outline_7", { "start" : vector(-definition.length / 2, definition.blockHeight), "end" : vector(-definition.length / 2, (0 * millimeter)) });
    skSolve(bodySketchSk);
    // Body
    opExtrude(context, id + "body" + "tool", { "entities" : qSketchRegion(id + "bodySketch"), "direction" : vector(0, -1, 0), "endBound" : BoundingType.BLIND, "endDepth" : (definition.depth) / 2, "startBound" : BoundingType.BLIND, "startDepth" : (definition.depth) / 2 });
    // Cradle sketch
    var cradleSketchSk = newSketchOnPlane(context, id + "cradleSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skCircle(cradleSketchSk, "cradle", { "center" : vector((0 * millimeter), definition.cradleHeight), "radius" : definition.cradleDiameter / 2 });
    skSolve(cradleSketchSk);
    // Cradle
    opExtrude(context, id + "cradle" + "tool", { "entities" : qSketchRegion(id + "cradleSketch"), "direction" : vector(0, -1, 0), "endBound" : BoundingType.BLIND, "endDepth" : (definition.depth + (2 * millimeter)) / 2, "startBound" : BoundingType.BLIND, "startDepth" : (definition.depth + (2 * millimeter)) / 2 });
    opBoolean(context, id + "cradle" + "bool", { "tools" : qCreatedBy(id + "cradle" + "tool", EntityType.BODY), "targets" : qSubtraction(qCreatedBy(id + "body", EntityType.BODY), qCreatedBy(id + "cradle" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // Mounting holes sketch
    var mountingHolesSketchSk = newSketchOnPlane(context, id + "mountingHolesSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(mountingHolesSketchSk, "plain", { "center" : vector(-definition.holeSpacing / 2, (0 * millimeter)), "radius" : definition.holeDiameter / 2 });
    skCircle(mountingHolesSketchSk, "tower", { "center" : vector(definition.holeSpacing / 2, (0 * millimeter)), "radius" : definition.holeDiameter / 2 });
    skSolve(mountingHolesSketchSk);
    // Mounting holes
    opExtrude(context, id + "mountingHoles" + "tool", { "entities" : qSketchRegion(id + "mountingHolesSketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.THROUGH_ALL });
    opBoolean(context, id + "mountingHoles" + "bool", { "tools" : qCreatedBy(id + "mountingHoles" + "tool", EntityType.BODY), "targets" : qSubtraction(qCreatedBy(id + "body", EntityType.BODY), qCreatedBy(id + "mountingHoles" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // Tower root fillets
    opFillet(context, id + "towerRootFillets", { "entities" : qIntersection([qAdjacent(qUnion([qParallelPlanes(qAdjacent(qFarthestAlong(qParallelPlanes(qCreatedBy(id + "body", EntityType.FACE), vector(0.0, 0.0, 1.0)), vector(0.0, 0.0, 1.0)), AdjacencyType.EDGE, EntityType.FACE), vector(1.0, 0.0, 0.0)), qParallelPlanes(qAdjacent(qFarthestAlong(qParallelPlanes(qCreatedBy(id + "body", EntityType.FACE), vector(0.0, 0.0, 1.0)), vector(0.0, 0.0, 1.0)), AdjacencyType.EDGE, EntityType.FACE), vector(-1.0, 0.0, 0.0))]), AdjacencyType.EDGE, EntityType.EDGE), qAdjacent(qSubtraction(qParallelPlanes(qCreatedBy(id + "body", EntityType.FACE), vector(0.0, 0.0, 1.0)), qFarthestAlong(qParallelPlanes(qCreatedBy(id + "body", EntityType.FACE), vector(0.0, 0.0, 1.0)), vector(0.0, 0.0, 1.0))), AdjacencyType.EDGE, EntityType.EDGE)]), "radius" : definition.towerFilletRadius });
    // Countersink
    opChamfer(context, id + "countersink", { "entities" : qGeometry(qAdjacent(qFarthestAlong(qParallelPlanes(qCreatedBy(id + "body", EntityType.FACE), vector(0.0, 0.0, 1.0)), vector(0.0, 0.0, 1.0)), AdjacencyType.EDGE, EntityType.EDGE), GeometryType.CIRCLE), "chamferType" : ChamferType.EQUAL_OFFSETS, "width" : (definition.countersinkDiameter - definition.holeDiameter) / 2 });
    // remove the construction sketches and curves
    opDeleteBodies(context, id + "cleanupSketches", { "entities" : qUnion([qCreatedBy(id + "bodySketch", EntityType.BODY), qCreatedBy(id + "cradleSketch", EntityType.BODY), qCreatedBy(id + "mountingHolesSketch", EntityType.BODY)]) });
    });
